<script setup lang="ts">
definePageMeta({ middleware:'admin' }); const supabase=useSupabaseClient(); const events=ref<any[]>([]); const sports=ref<any[]>([]); const teachers=ref<any[]>([])
const form=reactive({name:'',sport_id:null as number|null,year_level:null as number|null,gender:'mixed',event_date:'',start_time:'',location:'',teacher_id:null as string|null,status:'scheduled'})
const load=async()=>{const [e,s,t]=await Promise.all([supabase.from('events').select('*,sport:sports(name)').order('event_date'),supabase.from('sports').select('id,name').eq('active',true).order('name'),supabase.from('profiles').select('id,first_name,last_name').eq('role','teacher').eq('active',true).order('last_name')]);events.value=e.data||[];sports.value=s.data||[];teachers.value=t.data||[]}
const add=async()=>{await supabase.from('events').insert(form);form.name='';await load()}; onMounted(load)
</script>
<template><main class="mx-auto max-w-7xl px-4 py-8"><NuxtLink to="/admin" class="text-sm font-semibold text-blue-600">← Admin Dashboard</NuxtLink><h1 class="mt-3 text-3xl font-bold">Events</h1><form class="mt-6 grid gap-3 rounded-xl border bg-white p-5 md:grid-cols-3" @submit.prevent="add"><input v-model="form.name" required placeholder="Event name" class="rounded-lg border px-4 py-2 md:col-span-2"><select v-model="form.sport_id" required class="rounded-lg border px-4 py-2"><option :value="null">Select sport</option><option v-for="s in sports" :key="s.id" :value="s.id">{{s.name}}</option></select><input v-model.number="form.year_level" type="number" min="1" max="12" placeholder="Year level" class="rounded-lg border px-4 py-2"><select v-model="form.gender" class="rounded-lg border px-4 py-2"><option value="mixed">Mixed</option><option value="female">Girls</option><option value="male">Boys</option><option value="open">Open</option></select><input v-model="form.location" placeholder="Location" class="rounded-lg border px-4 py-2"><input v-model="form.event_date" type="date" required class="rounded-lg border px-4 py-2"><input v-model="form.start_time" type="time" class="rounded-lg border px-4 py-2"><select v-model="form.teacher_id" class="rounded-lg border px-4 py-2"><option :value="null">No teacher assigned</option><option v-for="t in teachers" :key="t.id" :value="t.id">{{t.first_name}} {{t.last_name}}</option></select><button class="rounded-lg bg-blue-600 px-5 py-2 font-semibold text-white md:col-span-3">Create Event</button></form><div class="mt-6 overflow-hidden rounded-xl border bg-white"><div v-for="e in events" :key="e.id" class="flex items-center gap-4 border-b p-4"><div class="flex-1"><div class="font-semibold">{{e.name}}</div><div class="text-sm text-slate-500">{{e.event_date}} · {{e.sport?.name}}</div></div><span class="capitalize">{{e.status.replaceAll('_',' ')}}</span></div></div></main></template>
